using System;
using System.Data;

// PROGRAM: Mengatur Isolation Level pada Transaksi ADO.NET / EF Core
public class BankingTransactionSimulator
{
    public static void ExecuteTransfer(string accountFrom, string accountTo, decimal amount, IsolationLevel level)
    {
        Console.WriteLine($"Memulai transaksi transfer dengan Isolation Level: {level}...");

        // Simulasi aturan transaksi
        if (level == IsolationLevel.ReadUncommitted)
        {
            Console.WriteLine("PERINGATAN: Berisiko membaca Dirty Read data belum ter-commit!");
        }
        else if (level == IsolationLevel.Snapshot || level == IsolationLevel.ReadCommitted)
        {
            Console.WriteLine("AMAN: Menggunakan proteksi pembacaan data ter-commit (MVCC/Read Committed).");
        }

        Console.WriteLine($"[COMMIT] Saldo Rp {amount:N0} berhasil ditransfer.");
    }
}

public class Program
{
    public static void Main()
    {
        BankingTransactionSimulator.ExecuteTransfer("ACC-1", "ACC-2", 250_000m, IsolationLevel.ReadCommitted);
        BankingTransactionSimulator.ExecuteTransfer("ACC-1", "ACC-2", 100_000m, IsolationLevel.Snapshot);
    }
}

