using System;

public class IsolationAnomalyChecker
{
    public static bool IsAnomalyPrevented(string isolationLevel, string anomalyType)
    {
        if (string.IsNullOrWhiteSpace(isolationLevel) || string.IsNullOrWhiteSpace(anomalyType))
            return false;

        string iso = isolationLevel.Trim().ToUpperInvariant();
        string anomaly = anomalyType.Trim().ToUpperInvariant();

        return anomaly switch
        {
            "DIRTYREAD" => iso is "READCOMMITTED" or "REPEATABLEREAD" or "SERIALIZABLE" or "SNAPSHOT",
            "NONREPEATABLEREAD" => iso is "REPEATABLEREAD" or "SERIALIZABLE" or "SNAPSHOT",
            "PHANTOMREAD" => iso is "SERIALIZABLE" or "SNAPSHOT",
            _ => false
        };
    }

    public static void Main()
    {
        Console.WriteLine(IsAnomalyPrevented("ReadCommitted", "DirtyRead"));
        Console.WriteLine(IsAnomalyPrevented("ReadCommitted", "NonRepeatableRead"));
        Console.WriteLine(IsAnomalyPrevented("Serializable", "PhantomRead"));
    }
}
